import { useEffect, useRef } from "react";
import { CoverWrapper } from "../covers/CoverWrapper";
import { GreetingPage } from "../GreetingPage";
import type { LayoutViewProps } from "../types";

/**
 * Responsive mosaic of every greeting at once. Autoplay is meaningless here, so
 * the presentation flags are intentionally ignored; the covers still bracket
 * the grid to keep the album's identity consistent across layouts.
 *
 * Seeking scrolls a card into view rather than turning to it, which is what
 * "navigating" a mosaic can mean — the editor's sync uses this to reveal the
 * greeting being edited among its neighbours.
 */
export function GridView({
  album,
  slides,
  onPageChange,
  bindNavigator,
}: LayoutViewProps) {
  const front = slides.find((slide) => slide.kind === "front-cover");
  const back = slides.find((slide) => slide.kind === "back-cover");
  const pages = slides.filter((slide) => slide.kind === "page");

  const itemRefs = useRef(new Map<string, HTMLElement>());
  const changeRef = useRef(onPageChange);
  changeRef.current = onPageChange;

  useEffect(() => {
    bindNavigator?.({
      get count() {
        return pages.length;
      },
      goto(index: number) {
        const slide = pages[index];
        if (!slide) return;
        changeRef.current?.(index);
        itemRefs.current.get(slide.key)?.scrollIntoView({
          behavior: "smooth",
          block: "nearest",
        });
      },
    });
    return () => bindNavigator?.(null);
    // Rebinding on page changes keeps the key map current after edits.
  }, [bindNavigator, pages]);

  return (
    <div className="ae-grid">
      {front ? (
        <header className="ae-grid__cover">
          <CoverWrapper album={album} face="front" />
        </header>
      ) : null}

      <div className="ae-grid__items">
        {pages.map((slide) => (
          <article
            key={slide.key}
            className="ae-grid__item"
            ref={(node) => {
              if (node) itemRefs.current.set(slide.key, node);
              else itemRefs.current.delete(slide.key);
            }}
          >
            {slide.kind === "page" ? (
              // Grid cards grow with their content, so a long greeting gets a
              // taller card instead of smaller type.
              <GreetingPage
                album={album}
                page={slide.page}
                part={slide.part}
                fitToPage={false}
              />
            ) : null}
          </article>
        ))}
      </div>

      {back ? (
        <footer className="ae-grid__cover">
          <CoverWrapper album={album} face="back" />
        </footer>
      ) : null}
    </div>
  );
}
